"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0960-11-13:0":{"b": ["Der fatimidische Befehlshaber Cevher es-Sıkıllî nahm Marokko ein (20 Ramazan 349).", "c5259a0b"], "d": ["Der fatimidische Befehlshaber Cevher es-Sıkıllî nahm Marokko ein (20 Ramazan 349).", "c5259a0b"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0961-10-15:0":{"b": ["Abdurrahman III. starb in Córdoba (2 Ramazan 350); das Kalifat ging an al-Hakam II. über.", "16c7e725"], "d": ["Abdurrahman III. starb in Córdoba (2 Ramazan 350); das Kalifat ging an al-Hakam II. über.", "16c7e725"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0972-01-01:0":{"b": ["Der fatimidische Kalif al-Mu'izz ernannte Bulukkîn zum Statthalter des Maghreb und ließ ihn in Kairouan nieder; die Zeit der Ziriden begann", "562089c8"], "d": ["Der fatimidische Kalif al-Mu'izz-Lidînillâh ernannte Bulukkîn b. Zîrî zum Statthalter des Maghreb und ließ ihn in Kairouan nieder (361/972); er verlegte das Verwaltungszentrum des Staates nach Ägypten und verließ die Region.", "26bbc5b2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0976-10-02:0":{"b": ["Nach dem Tod al-Hakams II. wurde der elf- bis zwölfjährige Hischam II. Kalif.", "359fba92"], "d": ["Nach dem Tod al-Hakams II. wurde der elf- bis zwölfjährige Hischam II. Kalif.", "359fba92"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1001-01-01:0":{"b": ["Fülfûl b. Saîd nahm Tripolis ein und gründete die Dynastie der Banu Hazrun (391, 1001).", "003ab80d"], "d": ["Fülfûl b. Saîd nahm Tripolis ein und gründete die Dynastie der Banu Hazrun (391, 1001).", "003ab80d"]},
